    SET NOCOUNT ON;
    DECLARE @jsonResult NVARCHAR(MAX);

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @action NVARCHAR(40) = JSON_VALUE(@pjsonfile, '$.marketingAds[0].action');
        DECLARE @companyId INT       = JSON_VALUE(@pjsonfile, '$.marketingAds[0].companyId');
        DECLARE @provider NVARCHAR(20) = JSON_VALUE(@pjsonfile, '$.marketingAds[0].provider');
        DECLARE @adId NVARCHAR(64)   = JSON_VALUE(@pjsonfile, '$.marketingAds[0].adId');

        IF @action = '1' -- Ensure pending row
        BEGIN
            DECLARE @mergeOutput TABLE (
                marketingAdId INT,
                lookupStatus NVARCHAR(20)
            );

            MERGE dbo.marketingAds AS target
            USING (SELECT @companyId AS companyId, @provider AS provider, @adId AS adId) AS source
            ON (target.companyId = source.companyId AND target.provider = source.provider AND target.adId = source.adId)
            WHEN NOT MATCHED BY TARGET THEN
                INSERT (companyId, provider, adId, lookupStatus, lookupAttempts, created_At, active)
                VALUES (source.companyId, source.provider, source.adId, 'pending', 0, SYSUTCDATETIME(), 1)
            OUTPUT inserted.marketingAdId, inserted.lookupStatus INTO @mergeOutput;

            -- If nothing was inserted, it means it matched an existing row.
            IF NOT EXISTS (SELECT 1 FROM @mergeOutput)
            BEGIN
                INSERT INTO @mergeOutput (marketingAdId, lookupStatus)
                SELECT marketingAdId, lookupStatus
                FROM dbo.marketingAds
                WHERE companyId = @companyId AND provider = @provider AND adId = @adId;
            END;

            SET @jsonResult = (
                SELECT marketingAdId, lookupStatus
                FROM @mergeOutput
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            );
        END

        ELSE IF @action = '2' -- Write lookup result
        BEGIN
            DECLARE @adName NVARCHAR(255)         = JSON_VALUE(@pjsonfile, '$.marketingAds[0].adName');
            DECLARE @adsetId NVARCHAR(64)         = JSON_VALUE(@pjsonfile, '$.marketingAds[0].adsetId');
            DECLARE @adsetName NVARCHAR(255)      = JSON_VALUE(@pjsonfile, '$.marketingAds[0].adsetName');
            DECLARE @campaignId NVARCHAR(64)      = JSON_VALUE(@pjsonfile, '$.marketingAds[0].campaignId');
            DECLARE @campaignName NVARCHAR(255)   = JSON_VALUE(@pjsonfile, '$.marketingAds[0].campaignName');
            DECLARE @adAccountId NVARCHAR(64)     = JSON_VALUE(@pjsonfile, '$.marketingAds[0].adAccountId');
            DECLARE @newLookupStatus NVARCHAR(20) = JSON_VALUE(@pjsonfile, '$.marketingAds[0].lookupStatus');
            DECLARE @lastError NVARCHAR(255)      = JSON_VALUE(@pjsonfile, '$.marketingAds[0].lastError');

            DECLARE @rowsAffected INT;

            UPDATE dbo.marketingAds
            SET
                lookupAttempts = lookupAttempts + 1,
                lastSyncedAt = SYSUTCDATETIME(),
                updated_at = SYSUTCDATETIME(),
                lookupStatus = @newLookupStatus,
                lastError = @lastError,
                adName = CASE WHEN @newLookupStatus = 'resolved' THEN LEFT(@adName, 255)
                              WHEN @newLookupStatus IN ('not_found', 'forbidden') THEN NULL
                              ELSE adName END,
                adsetId = CASE WHEN @newLookupStatus = 'resolved' THEN LEFT(@adsetId, 64)
                               WHEN @newLookupStatus IN ('not_found', 'forbidden') THEN NULL
                               ELSE adsetId END,
                adsetName = CASE WHEN @newLookupStatus = 'resolved' THEN LEFT(@adsetName, 255)
                                 WHEN @newLookupStatus IN ('not_found', 'forbidden') THEN NULL
                                 ELSE adsetName END,
                campaignId = CASE WHEN @newLookupStatus = 'resolved' THEN LEFT(@campaignId, 64)
                                  WHEN @newLookupStatus IN ('not_found', 'forbidden') THEN NULL
                                  ELSE campaignId END,
                campaignName = CASE WHEN @newLookupStatus = 'resolved' THEN LEFT(@campaignName, 255)
                                    WHEN @newLookupStatus IN ('not_found', 'forbidden') THEN NULL
                                    ELSE campaignName END,
                adAccountId = CASE WHEN @newLookupStatus = 'resolved' THEN LEFT(@adAccountId, 64)
                                   WHEN @newLookupStatus IN ('not_found', 'forbidden') THEN NULL
                                   ELSE adAccountId END
            WHERE
                companyId = @companyId AND provider = @provider AND adId = @adId;

            SET @rowsAffected = @@ROWCOUNT;

            IF @rowsAffected = 0
            BEGIN
                SET @jsonResult = '{"error":"ad_not_found"}';
            END
            ELSE
            BEGIN
                DECLARE @marketingAdId INT;
                SELECT @marketingAdId = marketingAdId
                FROM dbo.marketingAds
                WHERE companyId = @companyId AND provider = @provider AND adId = @adId;

                SET @jsonResult = (
                    SELECT @marketingAdId AS marketingAdId, 'updated' AS status
                    FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
                );
            END
        END

        ELSE
        BEGIN
            SET @jsonResult = '{"error":"unsupported_action"}';
        END

        COMMIT TRANSACTION;

        SELECT @jsonResult AS [jsonResult];

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @jsonResult = '{"error":"' + REPLACE(ERROR_MESSAGE(), '"', '''') + '"}';
        SELECT @jsonResult AS [jsonResult];
    END CATCH
END;
