import { useToast } from '../../../hooks/useToast';
import { onDataChanged } from '../../../utils/refreshBus';
import { MarketingAd } from '../../../api/marketingAdApi';

export const useMarketingAd = () => {
  const { companyId } = useUser();
  const { showToast, toastProps } = useToast();
  const [items, setItems] = useState<MarketingAd[]>([]); // Placeholder, no actual list to display
  const [loading, setLoading] = useState(false);

  // This module is worker-only with no direct frontend display for a list.
  // The load function is a placeholder to satisfy the MVVM pattern.
  const load = useCallback(async () => {
    setLoading(true);
    try {
      // No actual API call to fetch a list for display, as per PRD hints.
      // If an API call were needed for internal logic (e.g., specific stats), it would go here.
      setItems([]); // Keep items array empty
    } catch (err) {
      showToast((err as Error).message ?? 'Error desconocido al cargar', 'danger');
    } finally {
      setLoading(false);
    }
  }, [companyId, showToast]);

  useEffect(() => { load(); }, [load]);
  useIonViewWillEnter(() => { load(); });
  useEffect(() => onDataChanged(() => load()), [load]);

  return { items, loading, toastProps };
};

export type MarketingAdVM = ReturnType<typeof useMarketingAd>;
